/// <summary>
/// This is an extension class for <c>WMSPickingRegistration</c> form WMSPickingRoute datasource.
/// </summary>
[ExtensionOf(formDataSourceStr(WMSPickingRegistration, WMSPickingRoute))]
final class METWMSPickingRegistrationDS_Extension
{
}

Method.Source:
/// <summary>
/// Restrict Picking Routes by user restricted warehouses
/// </summary>
public void init()
{
    next init();

    QueryBuildDataSource wmsPickingRouteDS = this.query().dataSourceTable(tableNum(WMSPickingRoute));

    if (wmsPickingRouteDS && METSecurityPolicyHelper::isRoleActiveForCurrentUser(roleStr(METInventLocationPolicyRole)))
    {
        QueryBuildDataSource warehouseListDS = wmsPickingRouteDS.addDataSource(tableNum(METUserSecurityWarehouseList));
        warehouseListDS.joinMode(JoinMode::NoExistsJoin);
        warehouseListDS.relations(false);
        warehouseListDS.addLink(fieldNum(WMSPickingRoute, inventLocationId), fieldNum(METUserSecurityWarehouseList, InventLocationId));
        warehouseListDS.addLink(fieldNum(WMSPickingRoute, dataAreaId), fieldNum(METUserSecurityWarehouseList, Company));
        warehouseListDS.addRange(fieldNum(METUserSecurityWarehouseList, RestrictPickListRegistration)).value(queryValue(NoYes::Yes));

        QueryBuildDataSource securityGroupListDS = warehouseListDS.addDataSource(tableNum(METUserSecurityGroupList));
        securityGroupListDS.joinMode(JoinMode::ExistsJoin);
        securityGroupListDS.relations(false);
        securityGroupListDS.addLink(fieldNum(METUserSecurityWarehouseList, UserSecurityGroupId), fieldNum(METUserSecurityGroupList, UserSecurityGroupId));
        securityGroupListDS.addRange(fieldNum(METUserSecurityGroupList, UserId)).value(queryValue(curUserId()));
    }
}

/// <summary>
/// Extends the WmsPickingRoute data source query to apply filtering when the
/// form is opened from specific workbench menu items. The method inspects the
/// caller menu item and the record passed through Args to determine whether the
/// filter should be applied.
/// </summary>
/// <remarks>
/// When the form is launched from either METSalesOrderFinalizationWorkbench or
/// METTransferOrderFinalizationWorkbench, the method extracts the originating
/// SalesTable or InventTransferTable record and filters WmsPickingRoute by the
/// corresponding TransRefId (SalesId or TransferId).
///
/// The method preserves the base query behavior by calling next executeQuery().
/// </remarks>
/// <returns>
/// No return value. Modifies the underlying query by adding a range on
/// WmsPickingRoute.TransRefId when applicable.
/// </returns>
public void executeQuery()
{
    Args args = this.formRun().args();
    MenuItemName menuItem;

    if (args)
    {
        menuItem  = args.menuItemName();
    }

    if (menuItem
    && (menuItem ==  menuItemDisplayStr(METSalesOrderFinalizationWorkbench) ||
    menuItem == menuItemDisplayStr(METTransferOrderFinalizationWorkbench)))
    {
        SalesTable salesTable;
        InventTransferTable inventTrsnaferTable;
        METOrderReference orderRefNum;

        if (this.formRun().args().dataset() == tableNum(salesTable))
        {
            salesTable = this.formRun().args().record();
            orderRefNum = salesTable.SalesId;
        }
        else if (this.formRun().args().dataset() == tableNum(InventTransferTable))
        {
            inventTrsnaferTable = this.formRun().args().record();
            orderRefNum = inventTrsnaferTable.TransferId;
        }
        if (orderRefNum)
        {
            QueryBuildDataSource qbds = this.query().dataSourceTable(tableNum(WmsPickingRoute));
            QueryBuildRange      qbr;

            qbds.clearRanges();

            qbr = qbds.addRange(fieldNum(WmsPickingRoute, transRefId));
            qbr.value(orderRefNum);
        }
    }

    next executeQuery();
}

/// <summary>
/// Enable or disable the print button based on transaction type.
/// </summary>
/// <returns>Integer</returns>
public int active()
{
    int ret;

    ret = next active();

    FormControl ctrl = this.formRun().design().controlName(formControlStr(WMSPickingRegistration, PrintMenuButton));
    WMSPickingRoute wmsPickingRoute = this.cursor();
    FormControl WMSOrderTrans_METPickedCases = this.formRun().design().controlName(formControlStr(WMSPickingRegistration, WMSOrderTrans_METPickedCases));
    FormControl WMSOrderTrans_METPickedBrokenCases = this.formRun().design().controlName(formControlStr(WMSPickingRegistration, WMSOrderTrans_METPickedBrokenCases));

    if (wmsPickingRoute.transType == InventTransType::Sales)
    {
        WMSOrderTrans_METPickedCases.visible(true);
        WMSOrderTrans_METPickedBrokenCases.visible(true);
        ctrl.visible(true);
    }
    else
    {
        WMSOrderTrans_METPickedCases.visible(false);
        WMSOrderTrans_METPickedBrokenCases.visible(false);

        ctrl.visible(false);
    }

    return ret;
}

/// <summary>
/// Handles selection changes in the WMSPickingRoute data source.
/// Iterates through selected records and enables or disables the PickQtyUpdateButton
/// based on transaction type and expedition status.
/// </summary>
public void selectionChanged()
{
    WMSOrderTrans  wmsOrderTrans;
    InventDim      inventDim;
    InventLocation inventLocation;

    next selectionChanged();

    boolean canReviewSelection = true;

    FormControl ctrl = this.formRun().design().controlName(formControlStr(WMSPickingRegistration, PickQtyUpdateButton));

    FormDataSource  WMSPickingRouteDS = this;

    WMSPickingRoute currentLine = WMSPickingRouteDS.getFirst(1) ?
                                WMSPickingRouteDS.getFirst(1) :
                                WMSPickingRouteDS.cursor();

    if (!currentLine)
    {
        canReviewSelection = false;
    }

    while (currentLine && canReviewSelection)
    {
        if (currentLine.transType == InventTransType::Sales && currentLine.expeditionStatus == WMSExpeditionStatus::Activated)
        {
            select firstonly RecId from wmsOrderTrans
                where wmsOrderTrans.routeId == currentLine.pickingRouteID
                exists join inventDim
                    where inventDim.inventDimId == wmsOrderTrans.inventDimId
                exists join inventLocation
                    where inventLocation.InventLocationId == inventDim.InventLocationId &&
                        inventLocation.METCSDWarehouse == NoYes::Yes;

            if (wmsOrderTrans.RecId)
            {
                canReviewSelection = true;
            }
            else
            {
                canReviewSelection = false;
            }
        }
        else
        {
            canReviewSelection = false;
        }

        currentLine = WMSPickingRouteDS.getNext();
    }

    ctrl.enabled(canReviewSelection);
}
